-- The old role CHECK enumerated four roles, so remove it and use the
-- persisted preset catalogue as the source of valid IDs.
ALTER TABLE public.admins DROP CONSTRAINT IF EXISTS admins_role_check;
ALTER TABLE public.admins ADD CONSTRAINT admins_role_catalogue_fk
    FOREIGN KEY (role) REFERENCES public.committee_roles(id);
